<?php
declare(strict_types=1);require_once __DIR__.'/functions.php';require_login();$where=[];$params=[];$term=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');if($term!==''){$where[]='(u.name LIKE ? OR s.student_id_no LIKE ? OR s.course_year LIKE ?)';$like='%'.$term.'%';array_push($params,$like,$like,$like);}if(in_array($status,['Present','Late','Absent'],true)){$where[]='a.status = ?';$params[]=$status;}if($from!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='a.`date` >= ?';$params[]=$from;}if($to!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='a.`date` <= ?';$params[]=$to;}$sql='SELECT u.name,s.student_id_no,s.course_year,a.`date`,a.time_in,a.time_out,a.status FROM attendance_logs a JOIN students s ON s.id=a.student_id JOIN users u ON u.id=s.user_id';if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY a.`date` DESC,a.time_in DESC LIMIT 250';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();page_start('Attendance logs','attendance_logs.php');
?><div class="page-heading"><div><p class="overline">STUDENT RECORDS</p><h1>Attendance logs</h1><p class="heading-subtitle">Review and keep track of every student check-in.</p></div><span class="record-chip"><span>▤</span> <?=count($rows)?> records</span></div><section class="content-card report-card"><div class="card-heading report-heading"><div><h2>Attendance report</h2><p>Search, filter, and review attendance records</p></div></div><form method="get" class="filter-bar"><div class="search-field"><span>⌕</span><input name="q" type="search" placeholder="Search students or ID..." value="<?=e($term)?>"></div><div class="filter-control"><label for="from">FROM</label><input id="from" name="from" type="date" value="<?=e($from)?>"></div><div class="filter-control"><label for="to">TO</label><input id="to" name="to" type="date" value="<?=e($to)?>"></div><div class="filter-control status-filter"><label for="status">STATUS</label><select id="status" name="status"><option value="">All statuses</option><?php foreach(['Present','Late','Absent'] as $s):?><option <?=$status===$s?'selected':''?> value="<?=e($s)?>"><?=e($s)?></option><?php endforeach?></select></div><button class="btn btn-primary filter-button" type="submit">Apply filters</button><?php if($term||$status||$from||$to):?><a class="clear-filter" href="attendance_logs.php">Clear</a><?php endif?></form><div class="table-responsive"><table class="table activity-table report-table"><thead><tr><th>STUDENT</th><th>STUDENT ID</th><th>COURSE & YEAR</th><th>DATE</th><th>TIME IN</th><th>TIME OUT</th><th>STATUS</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty-state">No records found for these filters.</td></tr><?php else:foreach($rows as $r):?><tr><td><div class="student-cell"><span class="avatar student-avatar"><?=e(strtoupper(substr($r['name'],0,1)))?></span><strong><?=e($r['name'])?></strong></div></td><td class="table-secondary-text"><?=e($r['student_id_no'])?></td><td class="table-secondary-text"><?=e($r['course_year'])?></td><td class="table-secondary-text"><?=e(date('M j, Y',strtotime($r['date'])))?></td><td class="table-secondary-text"><?=$r['time_in']?e(date('g:i A',strtotime($r['time_in']))):'—'?></td><td class="table-secondary-text"><?=$r['time_out']?e(date('g:i A',strtotime($r['time_out']))):'—'?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;endif?></tbody></table></div><div class="table-footer"><span>Showing <?=count($rows)?> records <span class="footer-dot">·</span> Maximum 250 per view</span><span>Attendance records</span></div></section><?php page_end();
